// Deterministic local providers for end-to-end control-runtime acceptance.
// Git remains real; this provider has no network API or publication credentials.
import {writeFileSync,mkdirSync} from 'node:fs'
import path from 'node:path'
import {spawnSync} from 'node:child_process'
export function installSyntheticProviders(directory,{publicationFailure=null,initialFault=null}={}) {
 mkdirSync(directory,{recursive:true})
 writeFileSync(path.join(directory,'package.json'),JSON.stringify({type:'commonjs'}))
 const gh=`#!${process.execPath}
const fs=require('node:fs');const a=process.argv.slice(2),s=process.env.CP_SYNTHETIC_PROVIDER_STATE;
if(!s)process.exit(64);let prs=fs.existsSync(s)?JSON.parse(fs.readFileSync(s)):[];
if(a[0]==='api'){console.log(JSON.stringify([prs.map(p=>({number:p.number,state:'open',head:{ref:p.headRefName,repo:{full_name:'Synthetic/Disposable'}},base:{ref:p.baseRefName,repo:{full_name:'Synthetic/Disposable'}}}))]));process.exit(0)}
if(a[0]==='repo'){console.log(JSON.stringify({nameWithOwner:'Synthetic/Disposable'}));process.exit(0)}
if(a[0]!=='pr')process.exit(65);
if(a[1]==='list'){const i=a.indexOf('--head');console.log(JSON.stringify(i<0?prs:prs.filter(p=>p.headRefName===a[i+1])));process.exit(0)}
if(a[1]==='create'){if(!a.includes('--draft'))process.exit(78);const head=a[a.indexOf('--head')+1],base=a[a.indexOf('--base')+1];if(prs.some(p=>p.headRefName===head))process.exit(66);const p={number:9200+prs.length,headRefName:head,baseRefName:base,isDraft:true,url:'https://example.invalid/synthetic/'+(9200+prs.length),state:'OPEN',headRefOid:require('node:child_process').spawnSync('/usr/bin/git',['rev-parse','refs/heads/'+head],{encoding:'utf8'}).stdout.trim()};prs.push(p);fs.writeFileSync(s,JSON.stringify(prs));if(${JSON.stringify(publicationFailure)}==='pr'&&!fs.existsSync(s+'.crash-pr')){fs.writeFileSync(s+'.crash-pr','response-lost');process.exit(74)}console.log(p.url);process.exit(0)}
if(a[1]==='view'){console.log(JSON.stringify(prs.find(p=>p.headRefName===a[2]||String(p.number)===a[2])));process.exit(0)}process.exit(65)
`
 writeFileSync(path.join(directory,'gh'),gh,{mode:0o700})
 const codex=`#!${process.execPath}
const fs=require('node:fs'),path=require('node:path'),rl=require('node:readline');const a=process.argv.slice(2);
if(Object.keys(process.env).some(k=>/SECRET|TOKEN|PASSWORD|DB_URL|CONTROL_DB/i.test(k))){console.error('unexpected_model_child_credential');process.exit(77)}
if(a[0]==='app-server'){const lines=rl.createInterface({input:process.stdin});lines.on('line',line=>{const m=JSON.parse(line);if(m.id)process.stdout.write(JSON.stringify({id:m.id,result:m.id===2?{data:[{id:'gpt-6.1-sol',model:'gpt-6.1-sol',supportedReasoningEfforts:[{reasoningEffort:'medium'},{reasoningEffort:'high'}]},{id:'gpt-6-astra',model:'gpt-6-astra',supportedReasoningEfforts:[{reasoningEffort:'high'}]}]}:{}})+'\\n')});}
else if(a[0]==='exec'){let prompt='';process.stdin.on('data',s=>prompt+=s);process.stdin.on('end',async()=>{const cwd=a[a.indexOf('-C')+1]??process.cwd();if(${JSON.stringify(initialFault)}==='restart'||${JSON.stringify(initialFault)}?.startsWith('restore-'))await new Promise(r=>setTimeout(r,1500));if(fs.existsSync(path.join(cwd,'.local/synthetic-hooks'))){fs.writeFileSync(path.join(cwd,'.local/implementation-started'),JSON.stringify({pid:process.pid}));while(!fs.existsSync(path.join(cwd,'.local/implementation-release')))await new Promise(r=>setTimeout(r,100));}const restoreFault=${JSON.stringify(initialFault)};const counter=path.join(cwd,'.local/restore-implementation-count');const calls=Number(fs.existsSync(counter)?fs.readFileSync(counter):0)+1;if(restoreFault?.startsWith('restore-')){fs.mkdirSync(path.dirname(counter),{recursive:true});fs.writeFileSync(counter,String(calls));}const restoreDefect=path.basename(cwd).endsWith('cp-e2e-001')&&((restoreFault==='restore-fifth'&&calls<5)||(restoreFault==='restore-exhaust'&&calls<=5));const defect=restoreDefect||((fs.existsSync(path.join(cwd,'.local/product-defect'))||(${JSON.stringify(initialFault)}==='product-defect'&&path.basename(cwd).endsWith('cp-e2e-001')))&&!fs.existsSync(path.join(cwd,'.local/product-defect-investigated')));if(defect)fs.writeFileSync(path.join(cwd,'.local/product-defect-investigated'),'first-output');fs.mkdirSync(path.join(cwd,'src'),{recursive:true});fs.writeFileSync(path.join(cwd,'src/result.mjs'),'export const result='+JSON.stringify(defect?0:path.basename(cwd))+'\\n');if(${JSON.stringify(initialFault)}==='owner-scope'&&path.basename(cwd).endsWith('cp-e2e-001'))for(const name of ['brand','nuxt-layer','ui']){fs.mkdirSync(path.join(cwd,'packages',name),{recursive:true});fs.writeFileSync(path.join(cwd,'packages',name,'brand.mjs'),'export const brand = true\\n');}if(fs.existsSync(path.join(cwd,'.local/protected-task'))){fs.mkdirSync(path.join(cwd,'src/supabase/migrations'),{recursive:true});fs.writeFileSync(path.join(cwd,'src/supabase/migrations/synthetic-protected.sql'),'-- Disposable protected publication proof '+path.basename(cwd)+'\\n-- Publishing this file never applies a hosted database migration.\\n');}if(fs.existsSync(path.join(cwd,'.local/task-owned-output'))||${JSON.stringify(initialFault)}==='product-defect'||restoreFault?.startsWith('restore-'))fs.writeFileSync(path.join(cwd,'src/result.test.mjs'),"import assert from 'node:assert/strict';import {result} from './result.mjs';assert.equal(typeof result,'string')\\n");console.log(JSON.stringify({type:'turn.completed',usage:{input_tokens:1,output_tokens:1}}));});}else process.exit(65)
`
 writeFileSync(path.join(directory,'codex'),codex,{mode:0o700})
 const pnpm=spawnSync('which',['pnpm'],{encoding:'utf8'}).stdout.trim()
 if(!path.isAbsolute(pnpm))throw Error('fixture_pnpm_executable_required')
 const pause=`const fs=require('node:fs'),path=require('node:path'),cp=require('node:child_process');const cwd=process.cwd();function pause(phase){if(!fs.existsSync(path.join(cwd,'.local/synthetic-hooks')))return;fs.writeFileSync(path.join(cwd,'.local/'+phase+'-started'),JSON.stringify({pid:process.pid}));while(!fs.existsSync(path.join(cwd,'.local/'+phase+'-release')))Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,100);}`
 // A genuine successful install in the dependency-free Node fixture needs an
 // empty readiness directory. Never mask a failed install or real dependencies.
 writeFileSync(path.join(directory,'pnpm'),`#!${process.execPath}\n${pause}\nconst a=process.argv.slice(2);if(a[0]==='install')pause('verification');const result=cp.spawnSync(${JSON.stringify(pnpm)},a,{stdio:'inherit',env:process.env});if(a[0]==='install'&&result.status===0){const manifest=JSON.parse(fs.readFileSync(path.join(cwd,'package.json'),'utf8'));if(['dependencies','devDependencies','optionalDependencies'].every(key=>Object.keys(manifest[key]??{}).length===0))fs.mkdirSync(path.join(cwd,'node_modules'),{recursive:true});}process.exit(result.status??1)\n`,{mode:0o700})
 writeFileSync(path.join(directory,'git'),`#!${process.execPath}\n${pause}\nconst a=process.argv.slice(2);if(a[0]==='push')pause('publication');const result=cp.spawnSync('/usr/bin/git',a,{stdio:'inherit',env:process.env});const phase=${JSON.stringify(publicationFailure)},state=process.env.CP_SYNTHETIC_PROVIDER_STATE;if(result.status===0&&a[0]===phase&&state&&!fs.existsSync(state+'.crash-'+phase)){fs.writeFileSync(state+'.crash-'+phase,'response-lost');process.exit(74)}process.exit(result.status??1)\n`,{mode:0o700})
}
